const today = new Date();
const TERMS_VERSION = '2026-09-27';
const PRIVACY_VERSION = '2026-09-27';
const isoToday = today.toISOString().slice(0, 10);
const seededProfile = {firstName:'',lastName:'',grade:'9',school:'',state:'',gpa:'',major:'',career:'',colleges:[],courses:[],planned:[],activities:[],interests:[],goals:'',awards:[],competitions:[],volunteer:[],work:[],internships:[]};
let starterColleges = [];
let opportunities = [];
let state = loadState();
let currentUser = null;
let activePage = 'dashboard';
let opportunityFilter = 'All';
let taskFilter = 'All';
let collegeQuery = '';
let toastTimer;
let aiStatus = {checked:false,configured:false,model:'gpt-6-luna',reasoning:'high'};
function loadState(){return {profile:structuredClone(seededProfile),tasks:[],savedOpportunities:[],appliedOpportunities:[],completedOpportunities:[],savedColleges:[],messages:[],completedRoadmap:[],customColleges:[],applications:[]}}
let persistTimer=null,persistQueue=Promise.resolve();
function stateSnapshot(){return {profile:state.profile,tasks:state.tasks,messages:state.messages,savedColleges:state.savedColleges,savedOpportunities:state.savedOpportunities,appliedOpportunities:state.appliedOpportunities,completedOpportunities:state.completedOpportunities,completedRoadmap:state.completedRoadmap,customColleges:state.customColleges}}
function queueStateSave(){const snapshot=JSON.stringify(stateSnapshot());persistQueue=persistQueue.then(()=>fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:snapshot})).then(async r=>{if(!r.ok)throw new Error((await r.json()).error||'Could not save your changes.')}).catch(e=>{toast(e.message)});return persistQueue}
function persist(){updateChrome();if(!currentUser)return;clearTimeout(persistTimer);persistTimer=setTimeout(()=>{persistTimer=null;queueStateSave()},150)}
function flushStateSave(){if(!currentUser)return;clearTimeout(persistTimer);persistTimer=null;const body=JSON.stringify(stateSnapshot()),queued=navigator.sendBeacon&&navigator.sendBeacon('/api/state',new Blob([body],{type:'application/json'}));if(!queued)fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body,keepalive:true}).catch(()=>{})}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flushStateSave()});window.addEventListener('pagehide',flushStateSave);
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function updateChrome(){const p=state.profile;const full=`${p.firstName||'Student'} ${p.lastName||''}`.trim();document.getElementById('sideName').textContent=full;document.getElementById('sideGrade').textContent=`${p.grade||'9'}th grade · ${gradYear()}`;document.getElementById('avatar').textContent=(p.firstName||'S')[0].toUpperCase();document.getElementById('topAvatar').textContent=(p.firstName||'S')[0].toUpperCase();document.getElementById('taskCount').textContent=state.tasks.filter(t=>!t.done).length;document.getElementById('todayLabel').textContent=new Intl.DateTimeFormat('en-US',{weekday:'short',month:'short',day:'numeric'}).format(today)}
function gradYear(){return today.getFullYear()+(12-(Number(state.profile.grade)||9))}
function nav(page){activePage=page;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.getElementById('crumbCurrent').textContent=({dashboard:'Overview',advisor:'AI advisor',roadmap:'My roadmap',courses:'Course planner',colleges:'College list',opportunities:'Opportunities',activities:'Activities',tutor:'Study tutor',tasks:'Tasks & deadlines',profile:'My profile'})[page];document.getElementById('sidebar').classList.remove('open');render()}
function render(){updateChrome();const root=document.getElementById('pageContainer');const pages={dashboard:dashboardPage,advisor:advisorPage,roadmap:roadmapPage,courses:coursesPage,colleges:collegesPage,opportunities:opportunitiesPage,activities:activitiesPage,tutor:tutorPage,tasks:tasksPage,profile:profilePage};root.innerHTML=pages[activePage]();bindPageEvents()}
function pageHeader(eyebrow,title,subtitle,action=''){return `<div class="page-title-row"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="page-subtitle">${subtitle}</p></div>${action}</div>`}
function badge(text,kind=''){return `<span class="tag ${kind}">${esc(text)}</span>`}
function dashboardPage(){const p=state.profile;const priorities=[];if(Number(p.grade)<=10)priorities.push(['▤','Map out next year’s courses','Start with your school’s catalog and counselor.','courses']);else priorities.push(['▤','Review your course plan','Check prerequisites and graduation requirements.','courses']);if(p.major)priorities.push(['⌂',`Explore ${p.major} programs`,`Compare what your saved colleges offer.`,'colleges']);if((p.activities||[]).length<3)priorities.push(['◉','Try one interest-led activity','Explore an opportunity that fits what you enjoy.','opportunities']);else priorities.push(['◉','Make room for meaningful involvement','Reflect on what you want to learn through your activities.','activities']);priorities.push(['✳','Ask a question about your next step','Get a response grounded in your profile.','advisor']);const tasks=state.tasks.filter(t=>!t.done).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,3);const pct=Math.min(100,Math.round((Object.values(p).filter(v=>Array.isArray(v)?v.length>0:!!v).length/12)*100));const roadmap=roadmapData();return `${pageHeader('YOUR PERSONALIZED OVERVIEW',`Good ${greeting()}, ${esc(p.firstName||'there')}.`,`A little progress today adds up. Here’s what’s worth your attention.`)}<div class="welcome-banner"><div class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</div><h1>High school to college planning</h1><p>Keep your goals in view and take the next step at your own pace.</p><button class="btn btn-primary welcome-action" data-page="advisor">✳ &nbsp;Ask your AI advisor <span>→</span></button></div><div class="grid dashboard-grid"><section><div class="stat-row"><div class="stat-card"><span class="stat-icon">⌁</span><div class="stat-kicker">CURRENT GRADE</div><div class="stat-value">${esc(p.grade||'9')}<span style="font-size:12px">th</span></div><div class="stat-help">Class of ${gradYear()}</div></div><div class="stat-card"><span class="stat-icon">✦</span><div class="stat-kicker">INTENDED MAJOR</div><div class="stat-value" style="font-size:16px">${esc(p.major||'Explore')}</div><div class="stat-help">Your current direction</div></div><div class="stat-card"><span class="stat-icon">⌂</span><div class="stat-kicker">MY COLLEGES</div><div class="stat-value">${state.savedColleges.length}</div><div class="stat-help">Saved to your list</div></div></div><div class="panel"><div class="panel-head"><div><h2 class="panel-title">Your current priorities</h2><div class="panel-sub">A few personalized places to focus</div></div><a class="text-link" href="#tasks" data-page="tasks">View tasks →</a></div><div class="priority-list">${priorities.slice(0,4).map((x,i)=>`<div class="priority-item" data-page="${x[3]}"><div class="priority-icon">${x[0]}</div><div class="priority-copy"><strong>${esc(x[1])}</strong><span>${esc(x[2])}</span></div><span class="priority-arrow">→</span></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><div><h2 class="panel-title">Your roadmap</h2><div class="panel-sub">One year at a time</div></div><a class="text-link" href="#roadmap" data-page="roadmap">Open roadmap →</a></div><div class="roadmap-mini">${roadmap.slice(0,3).map((r,i)=>`<div class="roadmap-step"><div class="step-dot ${i===0?'now':''}">${i+1}</div><div class="step-copy"><strong>${esc(r.title)}</strong><span>${esc(r.items[0])}</span></div></div>`).join('')}</div><div style="margin-top:17px"><div class="progress-head"><strong>Profile completeness</strong><span>${pct}%</span></div><div class="progress-track"><span style="width:${pct}%"></span></div><div class="small-note">A more complete profile helps make your suggestions more relevant.</div></div></div></section><aside><div class="panel"><div class="panel-head"><div><h2 class="panel-title">Upcoming deadlines</h2><div class="panel-sub">Your personal to-do list</div></div><button class="text-link" data-action="add-task">+ Add</button></div>${tasks.length?tasks.map(t=>`<div class="deadline-row"><div class="date-box"><b>${t.due?new Date(`${t.due}T12:00:00`).getDate():'—'}</b><span>${t.due?new Date(`${t.due}T12:00:00`).toLocaleString('en-US',{month:'short'}):'OPEN'}</span></div><div class="deadline-copy"><strong>${esc(t.title)}</strong><span>${t.due?dateLabel(t.due):'No deadline set'}</span></div>${t.important?'<span class="priority-badge">SOON</span>':''}</div>`).join(''):`<div class="empty-state"><strong>A clear calendar.</strong>Add a task or deadline when you’re ready.</div>`}</div><div class="panel"><div class="panel-head"><div><h2 class="panel-title">At a glance</h2><div class="panel-sub">Your profile today</div></div><a class="text-link" href="#profile" data-page="profile">Edit</a></div><div class="tag-row">${badge(`${esc(p.school||'Add your school')}`)}${badge(`${esc(p.grade||'9')}th grade`,'blue')}${(p.colleges||[]).slice(0,3).map(c=>badge(c,'green')).join('')}</div><div style="margin-top:15px"><div class="progress-head"><strong>Planned courses</strong><span>${p.courses.length+(p.planned||[]).length}</span></div><div class="small-note">Course suggestions are starting points. Confirm plans with your counselor.</div></div></div><div class="panel"><div class="panel-head"><div><h2 class="panel-title">A note for your journey</h2></div><span style="color:#6174eb">✦</span></div><p class="context-hint">You don’t need a perfect plan today. Keep exploring what you enjoy, ask questions, and update your goals as they change.</p></div></aside></div>`}
function greeting(){const h=today.getHours();return h<12?'morning':h<17?'afternoon':'evening'}
function dateLabel(s){return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(new Date(`${s}T12:00:00`))}
function advisorPageLocalPreview(){const p=state.profile;const intro=aiStatus.configured?`Hi ${p.firstName||'there'}! I’m your AI advisor. I’ll use your profile to help you think through next steps. I use a higher reasoning setting, so replies may take a little longer.`:`Hi ${p.firstName||'there'}! I’m your advisor preview. I’ll use what you’ve shared about ${p.school||'your school'}, ${p.grade||'9'}th grade, and ${p.major||'your interests'} to help you think through next steps.\n\nConfigure a provider API key in the local Python app to enable live AI replies. For now, responses use local guidance templates.`;const msgs=state.messages.length?state.messages:[{role:'assistant',text:`${intro}\n\nWhat’s on your mind? I can help you explore course planning, colleges, activities, or deadlines. I’ll flag anything you should confirm with your counselor or an official source.`}];const live=aiStatus.configured;return `${pageHeader('YOUR PERSONALIZED GUIDE','Ask your advisor','A thoughtful starting point for your next question.')}<div class="chat-layout"><section class="panel chat-panel"><div class="chat-header"><div class="advisor-mark"><img src="/assets/logo.png" alt=""></div><div style="flex:1"><strong>Your advisor${live?' · AI':' · local preview'}</strong><span><i class="online-dot"></i>${live?`${esc(aiStatus.model)} · ${esc(aiStatus.reasoning)} reasoning`:'Profile-aware guided replies'}</span></div>${badge(live?'HIGH REASONING':'LOCAL PREVIEW','blue')}</div><div class="chat-messages" id="chatMessages">${msgs.map(messageHTML).join('')}</div><div class="chat-input-area"><form id="chatForm" class="chat-input-row"><input id="chatInput" autocomplete="off" placeholder="Ask about courses, colleges, or what to do next…"/><button class="send-button" aria-label="Send">↑</button></form><div class="suggestion-chips"><button class="chip" data-prompt="What should I think about for next year's courses?">Plan next year’s courses</button><button class="chip" data-prompt="How can I explore my intended major?">Explore my major</button><button class="chip" data-prompt="Help me find a meaningful activity connected to my interests.">Find an activity</button></div></div></section><aside><div class="panel context-card"><h3>What I know about you</h3><div class="context-line"><span>Grade</span><b>${esc(p.grade)}th · Class of ${gradYear()}</b></div><div class="context-line"><span>School</span><b>${esc(p.school||'Not added')}</b></div><div class="context-line"><span>Major</span><b>${esc(p.major||'Exploring')}</b></div><div class="context-line"><span>Colleges</span><b>${esc(p.colleges.join(', ')||'None saved')}</b></div><div class="context-line"><span>Activities</span><b>${p.activities.length} added</b></div><button class="text-link" data-page="profile" style="padding:10px 0 0">Update profile →</button></div><div class="panel context-card"><h3>How I can help</h3><p class="context-hint">${live?'Live responses use your profile, a higher reasoning effort, and a longer response timeout. Your chat and profile are sent to the model provider to answer; your account data is saved in this app.':'Local guided templates personalize suggestions with your profile. Add an API key to enable live advisor and tutor responses.'} Course catalogs, prerequisites, deadlines, and admissions policies change, so always confirm them with your school or official sources.</p></div></aside></div>`}
function messageHTML(m){return `<div class="message ${m.role==='user'?'user':''}">${m.role==='assistant'?'<div class="message-mark"><img src="/assets/logo.png" alt=""></div>':''}<div><div class="message-bubble">${esc(m.text)}</div><div class="message-meta">${m.role==='user'?'You':'Your advisor'}</div></div></div>`}
function advisorReply(input){const p=state.profile;const q=input.toLowerCase();const school=p.school||'your high school';const college=p.colleges.length?p.colleges.join(' and '):'colleges you may want to explore';const interest=p.interests.slice(0,2).join(' and ')||p.major||'your interests';const courses=p.courses.filter(c=>c.year===p.grade).map(c=>c.name);if(/course|class|take next|schedule|junior|senior/.test(q)){return `You’re in ${p.grade}th grade at ${school}${p.gpa?` and you’ve shared a ${p.gpa} GPA`:''}. You currently list ${courses.length?courses.join(', '):'no current courses for this grade'}.\n\nFor next year, start by checking your school’s course catalog and prerequisites with your counselor. Given your interest in ${p.major||interest}, you could ask whether courses like statistics, economics, or advanced math are available and fit your graduation plan. Those are ideas to investigate, not college requirements.\n\nI don’t have your school’s catalog yet. Add courses in Course planner to make this conversation more specific.`}
if(/college|admission|application|harvard|stanford|deadline|test/.test(q)){return `You’ve saved ${college}. For each one, start with the official admissions and academic-preparation pages linked in your College list; admissions requirements and deadlines can change.\n\nFor now, a useful next step at your grade level (${p.grade}th) is to explore what you enjoy in ${p.major||'your intended field'} and keep a balanced course plan with your counselor. No activity or course guarantees admission. Want me to help compare the programs you’ve saved?`}
if(/activity|extracurricular|club|volunteer|competition|internship/.test(q)){return `You’ve listed ${p.activities.join(', ')||'no activities yet'}, and you’re interested in ${interest}. You might explore one new way to connect those interests, such as an economics competition or a finance-themed project. The Federal Reserve and Council for Economic Education list programs to investigate in Opportunities.\n\nChoose something you’re genuinely curious about and check eligibility and timing on the official site. You don’t need to collect activities just to hit a number.`}
if(/major|career|finance|goal/.test(q)){return `You’re currently exploring ${p.major||'your intended major'}${p.career?` and a future as a ${p.career}`:''}. Since you also mentioned ${interest}, try a small exploration step: read about a real-world problem in that area, talk with a trusted adult who works in it, or compare how a few colleges describe their undergraduate programs.\n\nYour goal is: ${p.goals||'not added yet'}. What part would you like to explore first?`}
return `Based on what you’ve shared—${p.grade}th grade at ${school}, an interest in ${p.major||interest}, and goals around ${p.goals||'planning for the future'}—a useful next step is to pick one question you can answer this week. You could review next year’s course options with your counselor, explore a program at ${college}, or try one activity connected to ${interest}.\n\nWhich of those feels most useful right now?`}
function roadmapData(){const grade=Number(state.profile.grade)||9;const major=state.profile.major||'your areas of interest';return [9,10,11,12].filter(g=>g>=grade).map(g=>({grade:g,title:`${['','Freshman','Sophomore','Junior','Senior'][g]} year · Grade ${g}`,items:g===9?['Build a strong academic foundation','Explore subjects and activities that interest you','Learn how your school plans courses']:g===10?[`Explore ${major} through a project or activity`,'Review junior-year courses and prerequisites','Start a low-pressure college exploration list']:g===11?['Talk with your counselor about testing and course plans','Explore colleges and compare official program information','Reflect on meaningful activities and possible summer plans']:['Build an application timeline with your counselor','Review official college and scholarship deadlines','Compare financial aid options and make an informed choice']}))}
function roadmapPage(){const data=roadmapData();const total=data.reduce((n,y)=>n+y.items.length,0);const done=state.completedRoadmap.length;return `${pageHeader('YOUR PATH, YOUR PACE','My roadmap','A flexible guide shaped by your grade, interests, and goals.')}<div class="panel"><div class="panel-head"><div><h2 class="panel-title">Your high-school journey</h2><div class="panel-sub">These are suggested steps to explore, not admissions requirements.</div></div>${badge(`${done} of ${total} complete`,'blue')}</div><div class="progress-track" style="margin-bottom:17px"><span style="width:${total?Math.round(done/total*100):0}%"></span></div><div class="grid ${data.length===1?'':'two-col'}">${data.map((year,yi)=>`<div class="course-year"><div class="roadmap-year-head" style="padding:15px 16px 0"><h3>${esc(year.title)}</h3><span>${yi===0?'YOUR CURRENT STAGE':'LOOKING AHEAD'}</span></div><div class="roadmap-year">${year.items.map((it,ii)=>{const id=`${year.grade}-${ii}`,checked=state.completedRoadmap.includes(id);return `<div class="roadmap-item"><button class="roadmap-status ${checked?'done':''}" data-action="roadmap-toggle" data-id="${id}">${checked?'✓':yi===0&&ii===0?'•':''}</button><div class="roadmap-item-copy"><strong>${esc(it)}</strong><span>${roadmapHint(it)}</span></div></div>`}).join('')}</div></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><h2 class="panel-title">A reminder as you plan</h2></div><p class="context-hint">Every student’s path is different. Use this roadmap to start conversations with your counselor and adjust it as your plans change. College pages linked in your list are the source for current admissions details.</p></div>`}
function roadmapHint(t){if(/course|prerequisite/.test(t))return 'Review your school’s course catalog and confirm prerequisites with your counselor.';if(/college|program/.test(t))return 'Use official college pages and note the date you checked each detail.';if(/activity|project/.test(t))return 'Choose something you’re curious about and can stay engaged with.';return 'Take one manageable step and update this plan when your goals change.'}
function coursesPage(){const p=state.profile;const grades=[9,10,11,12];return `${pageHeader('PLAN WITH YOUR SCHOOL CATALOG','Course planner','Map current and future courses. Confirm every choice with your counselor.',`<button class="btn btn-primary" data-action="add-course">＋ Add a course</button>`)}<div class="panel"><div class="panel-head"><div><h2 class="panel-title">Your four-year view</h2><div class="panel-sub">Current courses, planned courses, and ideas to investigate</div></div>${badge(`${p.courses.length+p.planned.length} courses mapped`,'blue')}</div><div class="grid two-col">${grades.map(g=>{const list=[...p.courses,...p.planned].filter(c=>Number(c.year)===g);return `<div class="course-year"><div class="year-head"><h3>${['','Freshman','Sophomore','Junior','Senior'][g]} year</h3><span>GRADE ${g}${g===Number(p.grade)?' · CURRENT':''}</span></div><div class="course-list">${list.length?list.map((c,i)=>`<div class="course-row"><span class="course-color" style="background:${c.planned?'#bc83e4':'#3f88f4'}"></span><span class="course-name">${esc(c.name)}</span><span class="course-level">${esc(c.level)}${c.planned?' · PLAN':''}</span><button class="course-remove" title="Remove course" data-action="remove-course" data-name="${esc(c.name)}" data-year="${g}" data-planned="${!!c.planned}">×</button></div>`).join(''):'<div class="empty-state" style="padding:16px">No courses added for this year yet.</div>'}<button class="course-add" data-action="add-course" data-year="${g}">＋ Add course</button></div></div>`}).join('')}</div></div><div class="grid two-col"><div class="panel"><div class="panel-head"><h2 class="panel-title">Planning notes</h2></div><div class="tag-row">${badge(`Major: ${p.major||'Exploring'}`,'blue')}${badge(`School: ${p.school||'Add school'}`)}</div><p class="context-hint" style="margin-top:12px">${esc(p.major||'Your interests')} may lead you to investigate courses such as statistics, economics, writing, or advanced math if your school offers them and you meet prerequisites. These are exploration suggestions, not college requirements.</p></div><div class="panel"><div class="panel-head"><h2 class="panel-title">Before you finalize</h2></div><p class="context-hint">Check graduation requirements, course availability, workload, and prerequisites with your school counselor. Availability varies by school and year.</p></div></div>`}
function allColleges(){return [...starterColleges,...(state.customColleges||[])]}
function collegesPage(){const q=collegeQuery.toLowerCase();const list=allColleges().filter(c=>`${c.name} ${c.location} ${c.majors.join(' ')}`.toLowerCase().includes(q));return `${pageHeader('RESEARCH AT THE SOURCE','College list','Explore a small set of colleges and save the ones you want to learn about.',`<button class="btn btn-primary" data-action="add-college">＋ Add a college</button>`)}<div class="search-row"><div class="search-wrap"><input id="collegeSearch" class="search-input" placeholder="Search colleges or majors…" value="${esc(collegeQuery)}"/></div><span class="tag">${list.length} colleges</span></div><div class="panel" style="padding:13px 16px;margin-bottom:17px"><span class="context-hint"><strong style="color:#526078">Source-first research.</strong> Each profile links to official college information. Deadlines, requirements, and testing policies change. Confirm details directly before making decisions.</span></div>${list.length?`<div class="grid three-col">${list.map(c=>`<article class="card college-card"><div class="college-logo">${esc(c.initials)}</div><h3>${esc(c.name)}</h3><div class="college-location">⌖ &nbsp;${esc(c.location)}</div><p>${esc(c.summary)}</p><div class="tag-row">${c.majors.slice(0,2).map(m=>badge(m,'blue')).join('')}</div><div class="college-actions" style="margin-top:13px"><span class="source-note">Official source · ${esc(c.lastVerified)}</span><button class="text-link" data-action="college-detail" data-id="${esc(c.id)}">View profile →</button></div></article>`).join('')}</div>`:'<div class="empty-state"><strong>No matches.</strong>Try a different college or major.</div>'}<div class="panel" style="margin-top:17px"><div class="panel-head"><div><h2 class="panel-title">My colleges</h2><div class="panel-sub">Your saved shortlist</div></div><span class="tag blue">${state.savedColleges.length} saved</span></div>${state.savedColleges.length?`<div class="tag-row">${state.savedColleges.map(id=>{const c=allColleges().find(x=>x.id===id);return c?`<span class="tag green">${esc(c.name)} <button aria-label="Remove ${esc(c.name)}" data-action="unsave-college" data-id="${esc(id)}" style="border:0;background:none;color:inherit;cursor:pointer">×</button></span>`:''}).join('')}</div>`:'<div class="empty-state"><strong>Your list starts here.</strong>Save a college to keep its official links close.</div>'}</div>`}
function collegeDetail(id){const c=allColleges().find(x=>x.id===id);if(!c)return;const saved=state.savedColleges.includes(id);const sources=c.source&&c.source!=='#'?`<a href="${esc(c.source)}" target="_blank" rel="noopener">Admissions information ↗</a>${c.prepSource&&c.prepSource!==c.source?`<br/><a href="${esc(c.prepSource)}" target="_blank" rel="noopener">Academic preparation / requirements ↗</a>`:''}${c.aidSource?`<br/><a href="${esc(c.aidSource)}" target="_blank" rel="noopener">Financial aid information ↗</a>`:''}`:'No official source URL added yet. Add one to this college’s profile after confirming the school’s official website.';openModal(`<div class="modal-head"><div><div class="college-logo">${esc(c.initials)}</div><h2>${esc(c.name)}</h2><p>${esc(c.location)}</p></div><button class="modal-close" data-action="close-modal">×</button></div><div class="college-detail"><h4>Programs to explore</h4><div class="tag-row">${c.majors.length?c.majors.map(m=>badge(m,'blue')).join(''):'Not added'}</div><h4>Application information</h4><p>Use the official first-year admissions page for current required application components, application rounds, testing policy, and deadlines. This preview does not reproduce requirements that may change.</p><div class="tag-row">${badge('Required: see current official page','amber')}${badge('Recommended: not asserted')}${badge('General information')}</div><h4>Academic preparation</h4><p>Review the college’s curriculum guidance for recommendations, then compare with what your school offers. No course plan guarantees admission.</p><h4>Financial aid</h4><p>${esc(c.aid)}</p><h4>Official sources</h4><p>${sources}</p><p style="font-size:9px;color:#9aa2ae">${c.lastVerified==='Not verified'?'Custom entry · not verified':`Links reviewed ${esc(c.lastVerified)}. Always confirm details on the official pages.`}</p></div><div style="display:flex;gap:8px;margin-top:16px"><button class="btn ${saved?'btn-quiet':'btn-primary'}" data-action="save-college" data-id="${esc(id)}">${saved?'✓ Saved to My Colleges':'＋ Save to My Colleges'}</button><button class="btn btn-quiet" data-action="close-modal">Close</button></div>`)}
function opportunitiesPage(){const filtered=opportunities.filter(o=>opportunityFilter==='All'||o.category===opportunityFilter);return `${pageHeader('EXPLORE WHAT INTERESTS YOU','Opportunities','A starter collection to help you find programs, competitions, and ways to contribute.')}<div class="panel"><div class="panel-head"><div><h2 class="panel-title">Explore opportunities</h2><div class="panel-sub">Verify eligibility, dates, and costs with the official organizer.</div></div></div><div class="filter-tabs">${['All','Competitions','Programs','Summer programs','Volunteering','Scholarships'].map(f=>`<button class="filter-tab ${opportunityFilter===f?'active':''}" data-action="opportunity-filter" data-filter="${esc(f)}">${esc(f)}</button>`).join('')}</div></div><div class="grid three-col">${filtered.map(o=>{const saved=state.savedOpportunities.includes(o.id),applied=state.appliedOpportunities.includes(o.id),completed=state.completedOpportunities.includes(o.id);return `<article class="card resource-card"><div class="resource-top"><div class="resource-icon">✧</div>${badge(o.category,'blue')}</div><h3>${esc(o.name)}</h3><p>${esc(o.description)}</p><div class="resource-details">${esc(o.location)} · ${esc(o.deadline)}<br>Eligibility: ${esc(o.eligibility||"Check official site")}<br>Cost: ${esc(o.cost||"Check official source")}<br>Source checked ${esc(o.verified)}</div><div class="tag-row" style="margin-bottom:12px">${o.interests.slice(0,3).map(i=>badge(i)).join('')}</div><div class="resource-actions"><button class="btn ${saved?'btn-soft':'btn-quiet'}" data-action="toggle-opportunity" data-id="${esc(o.id)}">${saved?'✓ Saved':'☆ Save'}</button><button class="btn ${applied?'btn-soft':'btn-quiet'}" data-action="mark-applied" data-id="${esc(o.id)}">${completed?'✓ Completed':applied?'✓ Applied':'Mark applied'}</button><a class="btn btn-quiet" href="${esc(o.link)}" target="_blank" rel="noopener">Official site ↗</a></div></article>`}).join('')}</div><div class="panel" style="margin-top:17px"><p class="context-hint">Opportunity listings are discovery prompts. Confirm current dates, eligibility, costs, and accessibility with the official organization. Save items to find them again.</p></div>`}
function activitiesPage(){const p=state.profile;const recommendations=(p.major.toLowerCase().includes('fin')||p.interests.some(i=>/econ|business|entrepreneur|finance/i.test(i)))?[['♧','Economics competition','Try a team challenge to explore how economic ideas work in real life.'],['◇','Personal finance project','Build a simple budget or research a community financial question.'],['↗','Entrepreneurship','Explore a student business or pitch event in your area.']]:[['✦','Interest-led project','Choose a question you care about and create something to share.'],['◉','Community involvement','Look for a local group connected to a cause you value.'],['♧','Team activity','Try a club, competition, or sport where you can learn with others.']];return `${pageHeader('MAKE SPACE FOR WHAT YOU CARE ABOUT','Activities','Track meaningful involvement and explore ideas connected to your interests.',`<button class="btn btn-primary" data-action="add-activity">＋ Add an activity</button>`)}<div class="grid two-col"><section><div class="panel"><div class="panel-head"><div><h2 class="panel-title">Your activities</h2><div class="panel-sub">Focus on what you learn and contribute over time.</div></div>${badge(`${p.activities.length} activities`,'blue')}</div>${p.activities.length?`<div class="grid">${p.activities.map((a,i)=>`<article class="card activity-card"><div class="activity-head"><div class="activity-icon">${['◉','✦','♧'][i%3]}</div><div style="flex:1"><h3>${esc(a)}</h3><span>${esc(p.major||'Interest-led')}</span></div><button class="course-remove" data-action="remove-activity" data-index="${i}" title="Remove">×</button></div><p>Meaningful involvement grows through curiosity, contribution, and reflection. Add a note about your role and what you’re learning.</p><div class="activity-foot"><span>Part of your story</span>${badge('Edit in profile')}</div></article>`).join('')}</div>`:'<div class="empty-state"><strong>What do you enjoy doing?</strong>Add an activity to start shaping your plan.</div>'}</div><div class="panel"><div class="panel-head"><h2 class="panel-title">Your interests</h2><button class="text-link" data-page="profile">Edit interests →</button></div><div class="tag-row">${p.interests.map(i=>badge(i,'blue')).join('')||'<span class="context-hint">Add interests in your profile.</span>'}</div></div></section><aside><div class="panel"><div class="panel-head"><div><h2 class="panel-title">Ideas to explore</h2><div class="panel-sub">Based on ${esc(p.major||'your interests')}</div></div><span style="color:#6274eb">✦</span></div><div class="grid">${recommendations.map(x=>`<div class="priority-item"><div class="priority-icon">${x[0]}</div><div class="priority-copy"><strong>${esc(x[1])}</strong><span>${esc(x[2])}</span></div></div>`).join('')}</div><p class="context-hint" style="margin-top:14px">There’s no required number of activities. Explore what feels meaningful to you and verify program details with the organizers.</p><button class="btn btn-soft" data-page="opportunities" style="margin-top:13px">Explore opportunities →</button></div></aside></div>`}
function tasksPage(){let ts=[...state.tasks];if(taskFilter==='Open')ts=ts.filter(t=>!t.done);if(taskFilter==='Completed')ts=ts.filter(t=>t.done);ts.sort((a,b)=>(a.done?1:0)-(b.done?1:0)||(a.due||'9999').localeCompare(b.due||'9999'));return `${pageHeader('KEEP THE NEXT STEP VISIBLE','Tasks & deadlines','A simple place to track college planning and personal milestones.',`<button class="btn btn-primary" data-action="add-task">＋ Add a task</button>`)}<div class="panel"><div class="panel-head"><div><h2 class="panel-title">Your task list</h2><div class="panel-sub">${state.tasks.filter(t=>!t.done).length} open · ${state.tasks.filter(t=>t.done).length} completed</div></div><div class="filter-tabs">${['All','Open','Completed'].map(f=>`<button class="filter-tab ${taskFilter===f?'active':''}" data-action="task-filter" data-filter="${f}">${f}</button>`).join('')}</div></div>${ts.length?ts.map(t=>`<div class="task-row ${t.done?'complete':''}"><button class="task-check ${t.done?'checked':''}" data-action="toggle-task" data-id="${esc(t.id)}" aria-label="Mark task ${t.done?'open':'complete'}"></button><div class="task-main"><strong>${esc(t.title)}</strong><span>${esc(t.category||'Personal task')}${t.notes?` · ${esc(t.notes)}`:''}</span></div><span class="task-date">${t.due?dateLabel(t.due):'No due date'}</span><button class="course-remove" data-action="delete-task" data-id="${esc(t.id)}" title="Delete task">×</button></div>`).join(''):'<div class="empty-state"><strong>Nothing on this list yet.</strong>Add a task when you’re ready to take a next step.</div>'}</div>`}
function profilePage(){const p=state.profile;return `${pageHeader('A LIVING SNAPSHOT OF YOU','My profile','Update your details anytime. Your advisor uses this information to personalize suggestions.')}<form id="profileForm" class="panel profile-form"><div class="field"><label for="firstName">First name</label><input class="text-input" id="firstName" name="firstName" value="${esc(p.firstName)}" required></div><div class="field"><label for="lastName">Last name</label><input class="text-input" id="lastName" name="lastName" value="${esc(p.lastName)}"></div><div class="field"><label for="grade">Current grade</label><select class="select-input" id="grade" name="grade">${[9,10,11,12].map(g=>`<option value="${g}" ${Number(p.grade)===g?'selected':''}>${g}th grade</option>`).join('')}</select></div><div class="field"><label for="school">High school</label><input class="text-input" id="school" name="school" value="${esc(p.school)}" placeholder="School name"></div><div class="field"><label for="stateName">State / location</label><input class="text-input" id="stateName" name="state" value="${esc(p.state)}" placeholder="State"></div><div class="field"><label for="gpa">GPA <span class="field-hint">(optional)</span></label><input class="text-input" id="gpa" name="gpa" value="${esc(p.gpa)}" placeholder="e.g. 3.7"></div><div class="field"><label for="major">Intended major</label><input class="text-input" id="major" name="major" value="${esc(p.major)}" placeholder="A field you’re curious about"></div><div class="field"><label for="career">Career interests</label><input class="text-input" id="career" name="career" value="${esc(p.career)}" placeholder="Optional career ideas"></div><div class="field full"><label for="colleges">Target colleges / universities</label><input class="text-input" id="colleges" name="colleges" value="${esc(p.colleges.join(', '))}" placeholder="Separate colleges with commas"><span class="field-hint">Saved colleges in your College list are tracked separately.</span></div><div class="field full"><label for="coursesProfile">Current courses</label><textarea class="textarea-input" id="coursesProfile" name="courses" placeholder="One course per line">${esc(p.courses.map(c=>c.name).join('\n'))}</textarea></div><div class="field full"><label for="plannedProfile">Planned courses</label><textarea class="textarea-input" id="plannedProfile" name="planned" placeholder="One course per line">${esc(p.planned.map(c=>c.name).join('\n'))}</textarea></div><div class="field full"><label for="activitiesProfile">Activities</label><textarea class="textarea-input" id="activitiesProfile" name="activities" placeholder="One activity per line">${esc(p.activities.join('\n'))}</textarea></div><div class="field full"><label for="interestsProfile">Areas of interest</label><textarea class="textarea-input" id="interestsProfile" name="interests" placeholder="Economics, public speaking, biology…">${esc(p.interests.join(', '))}</textarea></div><div class="field full"><label for="goals">Academic goals</label><textarea class="textarea-input" id="goals" name="goals" placeholder="What would you like to work toward?">${esc(p.goals)}</textarea></div><div class="field-actions"><button type="reset" class="btn btn-quiet">Reset changes</button><button class="btn btn-primary">Save profile</button></div></form><div class="panel"><div class="panel-head"><h2 class="panel-title">Your information stays within your account</h2></div><p class="context-hint">Your profile and planning data are saved to your account on this app. Do not enter sensitive personal information. Review the Privacy Notice for details.</p></div>`}
function tutorPage(){return `${pageHeader('LEARN BY WORKING IT THROUGH','Study tutor','Get explanations, guided steps, practice prompts, and study plans.')}<div class="tutor-hero"><div class="eyebrow" style="color:#7871bd">LEARN IT, DON’T JUST LOOK IT UP</div><h2>Let’s make the hard part click.</h2><p>Pick a subject and tell me what you’re working on. I’ll guide the reasoning and invite you to try the next step.${aiStatus.configured?' The tutor uses the same higher reasoning setting.':' Configure an API key to enable live AI tutoring.'}</p></div><div class="grid two-col"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Start a tutoring session</h2><div class="panel-sub">Choose a course and learning mode</div></div><span class="advisor-mark">✎</span></div><form id="tutorForm"><div class="tutor-controls"><select class="select-input" id="tutorCourse"><option>Algebra 2</option><option>Chemistry</option><option>Biology</option><option>AP U.S. Government</option><option>AP U.S. History</option><option>AP English</option><option>Statistics</option><option>Physics</option><option>Economics</option><option>Other</option></select><select class="select-input" id="tutorMode"><option value="explain">Explain a concept</option><option value="steps">Step-by-step help</option><option value="practice">Practice questions</option><option value="quiz">Generate a quiz</option><option value="study">Make a study guide</option><option value="mistake">Understand a mistake</option></select></div><div class="field"><label for="tutorQuestion">What are you working on?</label><textarea class="textarea-input" id="tutorQuestion" placeholder="Describe a concept, question, or mistake. Share what you’ve tried so far."></textarea></div><button class="btn btn-primary">Start learning →</button></form><div id="tutorAnswer"></div></section><aside><div class="panel"><div class="panel-head"><h2 class="panel-title">How tutoring works</h2></div><div class="roadmap-mini"><div class="roadmap-step"><div class="step-dot now">1</div><div class="step-copy"><strong>Start with your thinking</strong><span>Tell me where it starts to feel confusing.</span></div></div><div class="roadmap-step"><div class="step-dot">2</div><div class="step-copy"><strong>Work one step at a time</strong><span>Get a hint and try the next move yourself.</span></div></div><div class="roadmap-step"><div class="step-dot">3</div><div class="step-copy"><strong>Check your understanding</strong><span>Practice again in your own words.</span></div></div></div></div><div class="panel"><div class="panel-head"><h2 class="panel-title">A good prompt</h2></div><p class="context-hint">“I’m studying quadratic functions. I understand factoring but get stuck choosing which method to use. Can you give me a hint first?”</p></div></aside></div>`}

function bindPageEvents(){document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>handleAction(el)));const form=document.getElementById('profileForm');if(form)form.addEventListener('submit',saveProfile);const search=document.getElementById('collegeSearch');if(search)search.addEventListener('input',()=>{const pos=search.selectionStart;collegeQuery=search.value;render();const next=document.getElementById('collegeSearch');next.focus();next.setSelectionRange(pos,pos)});const chat=document.getElementById('chatForm');if(chat)chat.addEventListener('submit',e=>{e.preventDefault();sendChat()});document.querySelectorAll('[data-prompt]').forEach(el=>el.addEventListener('click',()=>{document.getElementById('chatInput').value=el.dataset.prompt;sendChat()}));const tutor=document.getElementById('tutorForm');if(tutor)tutor.addEventListener('submit',e=>{e.preventDefault();tutorResponse()});}
function handleAction(el){const a=el.dataset.action,id=el.dataset.id;if(a==='add-task')taskModal();if(a==='add-course')courseModal(el.dataset.year||'');if(a==='remove-course'){const arr=el.dataset.planned==='true'?'planned':'courses';state.profile[arr]=state.profile[arr].filter(c=>!(c.name===el.dataset.name&&Number(c.year)===Number(el.dataset.year)));persist();render()}if(a==='college-detail')collegeDetail(id);if(a==='save-college'){if(!state.savedColleges.includes(id))state.savedColleges.push(id);persist();collegeDetail(id);toast('Added to My Colleges')}if(a==='unsave-college'){state.savedColleges=state.savedColleges.filter(x=>x!==id);persist();render();toast('Removed from My Colleges')}if(a==='add-college')collegeModal();if(a==='toggle-opportunity'){state.savedOpportunities=state.savedOpportunities.includes(id)?state.savedOpportunities.filter(x=>x!==id):[...state.savedOpportunities,id];persist();render();toast(state.savedOpportunities.includes(id)?'Opportunity saved':'Removed from saved opportunities')}if(a==='mark-applied'){const o=opportunities.find(x=>x.id===id);if(state.completedOpportunities.includes(id)){state.completedOpportunities=state.completedOpportunities.filter(x=>x!==id);state.appliedOpportunities=state.appliedOpportunities.filter(x=>x!==id)}else if(state.appliedOpportunities.includes(id)){state.completedOpportunities.push(id)}else {state.appliedOpportunities.push(id);state.savedOpportunities=[...new Set([...state.savedOpportunities,id])]}persist();render();toast(state.completedOpportunities.includes(id)?'Marked completed':state.appliedOpportunities.includes(id)?'Marked applied':'Updated')}if(a==='opportunity-filter'){opportunityFilter=el.dataset.filter;render()}if(a==='task-filter'){taskFilter=el.dataset.filter;render()}if(a==='toggle-task'){state.tasks=state.tasks.map(t=>t.id===id?{...t,done:!t.done}:t);persist();render()}if(a==='delete-task'){state.tasks=state.tasks.filter(t=>t.id!==id);persist();render();toast('Task removed')}if(a==='roadmap-toggle'){state.completedRoadmap=state.completedRoadmap.includes(id)?state.completedRoadmap.filter(x=>x!==id):[...state.completedRoadmap,id];persist();render()}if(a==='add-activity')activityModal();if(a==='remove-activity'){state.profile.activities.splice(Number(el.dataset.index),1);persist();render();toast('Activity removed')}if(a==='close-modal')closeModal()}
function openModal(html){const back=document.getElementById('modalBackdrop');document.getElementById('modal').innerHTML=html;back.hidden=false;back.onclick=e=>{if(e.target===back)closeModal()};document.querySelectorAll('#modal [data-action]').forEach(el=>el.addEventListener('click',()=>handleAction(el)));}
function closeModal(){document.getElementById('modalBackdrop').hidden=true;document.getElementById('modal').innerHTML=''}
function taskModal(){openModal(`<div class="modal-head"><div><h2>Add a task</h2><p>Keep your next step somewhere you can find it.</p></div><button class="modal-close" data-action="close-modal">×</button></div><form class="modal-form" id="taskForm"><div class="field"><label for="taskTitle">Task</label><input class="text-input" id="taskTitle" name="title" required placeholder="e.g. Ask counselor about junior-year courses"></div><div class="field"><label for="taskDue">Due date</label><input class="text-input" id="taskDue" name="due" type="date"></div><div class="field"><label for="taskCategory">Category</label><select class="select-input" id="taskCategory" name="category"><option>Course planning</option><option>College research</option><option>Application</option><option>Opportunity</option><option>Personal goal</option></select></div><div class="field"><label for="taskNotes">Notes <span class="field-hint">(optional)</span></label><input class="text-input" id="taskNotes" name="notes" placeholder="A reminder for yourself"></div><div class="field-actions"><button type="button" class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary">Add task</button></div></form>`);document.getElementById('taskForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);state.tasks.push({id:uid(),title:f.get('title'),due:f.get('due'),category:f.get('category'),notes:f.get('notes'),done:false});persist();closeModal();render();toast('Task added')})}
function courseModal(year=''){const p=state.profile;openModal(`<div class="modal-head"><div><h2>Add a course</h2><p>Record current courses or ideas to discuss with your counselor.</p></div><button class="modal-close" data-action="close-modal">×</button></div><form class="modal-form" id="courseForm"><div class="field"><label for="courseName">Course name</label><input class="text-input" id="courseName" name="name" required placeholder="e.g. Statistics"></div><div class="field"><label for="courseLevel">Level</label><select class="select-input" id="courseLevel" name="level"><option>Standard</option><option>Honors</option><option>AP</option><option>Dual Enrollment</option><option>Other</option></select></div><div class="field"><label for="courseYear">Grade / year</label><select class="select-input" id="courseYear" name="year">${[9,10,11,12].map(g=>`<option value="${g}" ${Number(year||p.grade)===g?'selected':''}>${g}th grade</option>`).join('')}</select></div><div class="field"><label for="coursePrereq">Prerequisites</label><input class="text-input" id="coursePrereq" name="prereq" placeholder="If known; confirm with school"></div><div class="field"><label for="courseCredits">Credits</label><input class="text-input" id="courseCredits" name="credits" type="number" step="0.5" min="0" placeholder="Optional"></div><label style="display:flex;gap:8px;align-items:center;font-size:10px;color:#59657b"><input type="checkbox" name="planned" checked> Mark as planned / potential</label><div class="field-actions"><button type="button" class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary">Save course</button></div></form>`);document.getElementById('courseForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const c={name:f.get('name'),level:f.get('level'),year:f.get('year'),prereq:f.get('prereq'),credits:f.get('credits'),planned:f.has('planned')};state.profile[c.planned?'planned':'courses'].push(c);persist();closeModal();render();toast('Course added')})}
function activityModal(){openModal(`<div class="modal-head"><div><h2>Add an activity</h2><p>Track a club, sport, project, job, or way you contribute.</p></div><button class="modal-close" data-action="close-modal">×</button></div><form class="modal-form" id="activityForm"><div class="field"><label for="activityName">Activity</label><input class="text-input" id="activityName" required placeholder="e.g. Robotics club"></div><div class="field-actions"><button type="button" class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary">Add activity</button></div></form>`);document.getElementById('activityForm').addEventListener('submit',e=>{e.preventDefault();state.profile.activities.push(document.getElementById('activityName').value.trim());persist();closeModal();render();toast('Activity added')})}
function collegeModal(){openModal(`<div class="modal-head"><div><h2>Add a college</h2><p>Add a school to your research list. Use official sources to verify its details.</p></div><button class="modal-close" data-action="close-modal">×</button></div><form class="modal-form" id="collegeForm"><div class="field"><label for="customCollege">University name</label><input class="text-input" id="customCollege" required placeholder="College or university"></div><div class="field"><label for="customLocation">Location</label><input class="text-input" id="customLocation" placeholder="City, state"></div><div class="field"><label for="customMajor">Programs to explore</label><input class="text-input" id="customMajor" placeholder="Optional; separate with commas"></div><div class="field"><label for="customUrl">Official admissions URL</label><input class="text-input" id="customUrl" type="url" placeholder="https://…"><span class="field-hint">We don’t create admissions claims for custom colleges.</span></div><div class="field-actions"><button type="button" class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary">Add college</button></div></form>`);document.getElementById('collegeForm').addEventListener('submit',e=>{e.preventDefault();const name=document.getElementById('customCollege').value.trim(),url=document.getElementById('customUrl').value.trim();let valid='';try{if(url){const u=new URL(url);if(u.protocol==='https:')valid=u.href}}catch{}const c={id:`custom-${uid()}`,name,location:document.getElementById('customLocation').value.trim()||'Location not added',initials:name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase(),majors:document.getElementById('customMajor').value.split(',').map(x=>x.trim()).filter(Boolean),summary:'Custom entry. Confirm all admissions and program information on official college sources.',source:valid||'#',prepSource:valid||'#',lastVerified:'Not verified',aid:'Review the college’s official financial aid pages.'};state.customColleges=[...(state.customColleges||[]),c];state.savedColleges.push(c.id);persist();closeModal();render();toast('College added to My Colleges')})}
function saveProfile(e){e.preventDefault();const f=new FormData(e.currentTarget),p=state.profile,grade=f.get('grade');const names=f.get('courses').split('\n').map(x=>x.trim()).filter(Boolean);const oldCurrent=p.courses||[];p.firstName=f.get('firstName').trim();p.lastName=f.get('lastName').trim();p.grade=grade;p.school=f.get('school').trim();p.state=f.get('state').trim();p.gpa=f.get('gpa').trim();p.major=f.get('major').trim();p.career=f.get('career').trim();p.colleges=f.get('colleges').split(',').map(x=>x.trim()).filter(Boolean);p.courses=names.map(name=>({...oldCurrent.find(c=>c.name===name),name,level:oldCurrent.find(c=>c.name===name)?.level||'Standard',year:grade}));p.planned=f.get('planned').split('\n').map(x=>x.trim()).filter(Boolean).map(name=>({name,level:'Standard',year:String(Math.min(12,Number(grade)+1)),planned:true}));p.activities=f.get('activities').split('\n').map(x=>x.trim()).filter(Boolean);p.interests=f.get('interests').split(',').map(x=>x.trim()).filter(Boolean);p.goals=f.get('goals').trim();persist();render();toast('Profile saved')}
async function callAi(message,mode='advisor',history=[]){const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,mode,history,profile:state.profile})});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'AI request failed.');return result.reply}
async function checkAI(){try{const response=await fetch('/api/health',{cache:'no-store'});if(!response.ok)return;const data=await response.json();aiStatus={checked:true,configured:!!data.ai_configured,model:data.model||'gpt-6-luna',reasoning:data.reasoning_effort||'high'};if(activePage==='advisor'||activePage==='tutor')render()}catch{aiStatus.checked=true;aiStatus.configured=false}}
async function sendChatLocalPreview(){const inp=document.getElementById('chatInput');const text=inp.value.trim();if(!text)return;await checkAI();const history=state.messages.map(m=>({role:m.role,content:m.text}));state.messages.push({role:'user',text});if(aiStatus.configured){state.messages.push({role:'assistant',text:'Thinking carefully about your question…'});render();document.querySelectorAll('#chatForm input,#chatForm button').forEach(el=>el.disabled=true);try{state.messages[state.messages.length-1].text=await callAi(text,'advisor',history)}catch(error){state.messages[state.messages.length-1].text=`I couldn’t reach the AI service (${error.message}). Here’s a local planning suggestion instead:\n\n${advisorReply(text)}`} }else{state.messages.push({role:'assistant',text:advisorReply(text)})}persist();render();const box=document.getElementById('chatMessages');box.scrollTop=box.scrollHeight}
async function tutorResponseLocalPreview(){const course=document.getElementById('tutorCourse').value,mode=document.getElementById('tutorMode').value,q=document.getElementById('tutorQuestion').value.trim();if(!q){toast('Add a concept or question to get started');return}await checkAI();const answer=document.getElementById('tutorAnswer');const button=document.querySelector('#tutorForm button[type="submit"]');if(button)button.disabled=true;answer.innerHTML='<div class="panel thinking" style="margin-top:16px">Working through this with you…</div>';let reply;try{reply=aiStatus.configured?await callAi(`Course: ${course}\nLearning mode: ${mode}\nStudent question or topic: ${q}`,'tutor'):localTutorReply(course,mode,q)}catch(error){reply=`The AI service could not be reached (${error.message}).\n\n${localTutorReply(course,mode,q)}`}answer.innerHTML=`<div class="panel" style="background:#f8f8ff;margin:16px 0 0;border-color:#e5e7fb"><div class="eyebrow" style="color:#3178df">${aiStatus.configured?'AI TUTOR':'GUIDED PREVIEW'} · ${esc(course.toUpperCase())}</div><p style="white-space:pre-wrap;font-size:11px;line-height:1.7;color:#56627a">${esc(reply)}</p><span class="field-hint">Work through the reasoning, then check your class materials and teacher guidance.</span></div>`;if(button)button.disabled=false}
function localTutorReply(course,mode,q){const prompt=esc(q),subject=esc(course);const modes={explain:`Let’s make ${prompt} more manageable in ${subject}. First, tell me what you already know about it.\n\nA useful way to begin: identify the key idea, connect it to an example you understand, then test the connection with one small problem. What part feels least clear?`,steps:`We can work through ${prompt} in ${subject} one step at a time.\n\nStep 1: Write down what the question gives you and what it asks you to find.\nStep 2: Choose a rule, definition, or representation that connects those pieces.\n\nTry the first step in your own words and share it here.`,practice:`Try these ${subject} practice prompts about ${prompt}.\n\n1. Explain the central idea in one sentence.\n2. Make a simple example that uses the idea.\n3. What would change if one condition in your example changed?\n\nTry them before looking up a solution.`,quiz:`Quick self-check for ${subject}: ${prompt}\n\n1. Define the key term or principle.\n2. Apply it to a new example.\n3. Explain one common mistake and how you would catch it.\n\nWrite your answers first, then check your notes.`,study:`A simple study guide outline for ${subject} — ${prompt}\n\n• Core question: What problem does this concept help solve?\n• Key ideas: list the terms, formulas, or events you need to recognize.\n• Worked example: explain each step and why it is valid.\n• Retrieval practice: close your notes and summarize from memory.\n• Review: revisit what you couldn’t explain yet.`,mistake:`Let’s learn from the ${subject} mistake in “${prompt}”.\n\nFind the first line where your reasoning changed direction. Check the sign, units, definition, or assumption there. What step are you unsure about, and what did you expect to happen?`};return modes[mode]||modes.explain}
function uid(){return Math.random().toString(36).slice(2,10)}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){e.preventDefault();nav(b.dataset.page)}});
document.getElementById('mobileMenu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});

// Live advisor/tutor overrides: the original local templates remain the no-key fallback.
function advisorPage(){const p=state.profile,live=aiStatus.configured;const intro=live?`Hi ${p.firstName||'there'}! I’m your AI advisor. I’ll use your profile to help you think through next steps. I use a higher reasoning setting, so replies may take a little longer.`:`Hi ${p.firstName||'there'}! I’m your advisor preview. I’ll use what you’ve shared about ${p.school||'your school'}, ${p.grade||'9'}th grade, and ${p.major||'your interests'} to help you think through next steps.\n\nConfigure a provider API key in the local Python app to enable live AI replies. For now, responses use local guidance templates.`;const msgs=state.messages.length?state.messages:[{role:'assistant',text:`${intro}\n\nWhat’s on your mind? I can help you explore courses, colleges, activities, or deadlines. Confirm school-specific details with your counselor and current requirements with official sources.`}];return `${pageHeader('YOUR PERSONALIZED GUIDE','Ask your advisor','A thoughtful starting point for your next question.')}<div class="chat-layout"><section class="panel chat-panel"><div class="chat-header"><div class="advisor-mark"><img src="/assets/logo.png" alt=""></div><div style="flex:1"><strong>Your advisor${live?' · AI':' · local preview'}</strong><span><i class="online-dot"></i>${live?`${esc(aiStatus.model)} · ${esc(aiStatus.reasoning)} reasoning`:'Profile-aware guided replies'}</span></div>${badge(live?'HIGH REASONING':'LOCAL PREVIEW','blue')}</div><div class="chat-messages" id="chatMessages">${msgs.map(messageHTML).join('')}</div><div class="chat-input-area"><form id="chatForm" class="chat-input-row"><input id="chatInput" autocomplete="off" placeholder="Ask about courses, colleges, or what to do next…"/><button class="send-button" aria-label="Send">↑</button></form><div class="suggestion-chips"><button class="chip" data-prompt="What should I think about for next year's courses?">Plan next year’s courses</button><button class="chip" data-prompt="How can I explore my intended major?">Explore my major</button><button class="chip" data-prompt="Help me find a meaningful activity connected to my interests.">Find an activity</button></div></div></section><aside><div class="panel context-card"><h3>What I know about you</h3><div class="context-line"><span>Grade</span><b>${esc(p.grade)}th · Class of ${gradYear()}</b></div><div class="context-line"><span>School</span><b>${esc(p.school||'Not added')}</b></div><div class="context-line"><span>Major</span><b>${esc(p.major||'Exploring')}</b></div><div class="context-line"><span>Colleges</span><b>${esc(p.colleges.join(', ')||'None saved')}</b></div><div class="context-line"><span>Activities</span><b>${p.activities.length} added</b></div><button class="text-link" data-page="profile" style="padding:10px 0 0">Update profile →</button></div><div class="panel context-card"><h3>How I can help</h3><p class="context-hint">${live?'Live responses use your profile and a higher reasoning effort. Your question and relevant profile details are sent to the configured model provider; planner and profile data are saved to your account on this app.':'Local guided templates personalize suggestions with your profile. Add an API key to enable live AI responses.'} Always confirm course choices with your counselor and current admissions facts with official sources.</p></div></aside></div>`}

async function sendChat(){const input=document.getElementById('chatInput');const text=input.value.trim();if(!text)return;await checkAI();const history=state.messages.map(m=>({role:m.role,content:m.text}));state.messages.push({role:'user',text});state.messages.push({role:'assistant',text:aiStatus.configured?'Thinking carefully about your question…':advisorReply(text)});render();if(aiStatus.configured){document.querySelectorAll('#chatForm input,#chatForm button').forEach(el=>el.disabled=true);try{state.messages[state.messages.length-1].text=await callAi(text,'advisor',history)}catch(error){state.messages[state.messages.length-1].text=`I couldn’t reach the AI service (${error.message}). Here’s a local planning suggestion instead:\n\n${advisorReply(text)}`}}persist();render();const box=document.getElementById('chatMessages');box.scrollTop=box.scrollHeight}

function localTutorReply(course,mode,q){const modes={explain:`Let’s make ${q} more manageable in ${course}. First, tell me what you already know about it.\n\nIdentify the key idea, connect it to an example you understand, then test it with one small problem. What part feels least clear?`,steps:`We can work through ${q} in ${course} one step at a time.\n\nFirst, write what the question gives you and what it asks you to find. Then choose a rule, definition, or representation that connects those pieces. What would you write first?`,practice:`Try these ${course} practice prompts about ${q}.\n\n1. Explain the central idea in one sentence.\n2. Make a simple example that uses the idea.\n3. What would change if one condition in your example changed?\n\nTry them before looking up a solution.`,quiz:`Quick self-check for ${course}: ${q}\n\n1. Define the key term or principle.\n2. Apply it to a new example.\n3. Explain one common mistake and how you would catch it.\n\nWrite your answers first, then check your notes.`,study:`A simple study guide outline for ${course} — ${q}\n\n• Core question: What problem does this concept help solve?\n• Key ideas: list the terms, formulas, or events you need to recognize.\n• Worked example: explain each step and why it is valid.\n• Retrieval practice: close your notes and summarize from memory.\n• Review: revisit what you couldn’t explain yet.`,mistake:`Let’s learn from the ${course} mistake in “${q}”.\n\nFind the first line where your reasoning changed direction. Check the sign, units, definition, or assumption there. What step are you unsure about, and what did you expect to happen?`};return modes[mode]||modes.explain}

async function tutorResponse(){const course=document.getElementById('tutorCourse').value,mode=document.getElementById('tutorMode').value,q=document.getElementById('tutorQuestion').value.trim();if(!q){toast('Add a concept or question to get started');return}await checkAI();const answer=document.getElementById('tutorAnswer'),button=document.querySelector('#tutorForm button');if(button)button.disabled=true;answer.innerHTML='<div class="panel thinking" style="margin-top:16px">Working through this with you…</div>';let reply;try{reply=aiStatus.configured?await callAi(`Course: ${course}\nLearning mode: ${mode}\nStudent question or topic: ${q}`,'tutor'):localTutorReply(course,mode,q)}catch(error){reply=`The AI service could not be reached (${error.message}).\n\n${localTutorReply(course,mode,q)}`}answer.innerHTML=`<div class="panel" style="background:#f8f8ff;margin:16px 0 0;border-color:#e5e7fb"><div class="eyebrow" style="color:#3178df">${aiStatus.configured?'AI TUTOR':'GUIDED PREVIEW'} · ${esc(course.toUpperCase())}</div><p style="white-space:pre-wrap;font-size:11px;line-height:1.7;color:#56627a">${esc(reply)}</p><span class="field-hint">Work through the reasoning, then check your class materials and teacher guidance.</span></div>`;if(button)button.disabled=false}

