// Authenticated application shell and release-candidate workflows.
let selectedAuthMode='login', schoolCourses=[], adminUsers=[], adminOverview={};
const baseUpdateChrome=updateChrome;
function authPage(){const registering=selectedAuthMode==='register';return `<div class="auth-shell"><section class="auth-card"><div class="brand"><img class="brand-logo" src="/assets/logo.png" alt=""><span>Student planning workspace</span></div><div class="eyebrow">PRIVATE STUDENT WORKSPACE</div><h1>${registering?'Create your account':selectedAuthMode==='reset'?'Reset your password':'Welcome back'}</h1><p class="page-subtitle">Your profile, plans, and conversations stay within your account.</p><form id="authForm" class="modal-form"><div class="field"><label>Email</label><input class="text-input" name="email" type="email" autocomplete="email" required></div>${selectedAuthMode==='reset'?`<div class="field"><label>Reset code</label><input class="text-input" name="token" autocomplete="one-time-code" placeholder="Paste the code from your reset request"></div><div class="field"><label>New password</label><input class="text-input" name="password" type="password" minlength="10" required></div>`:selectedAuthMode==='request-reset'?'':`<div class="field"><label>Password</label><input class="text-input" name="password" type="password" minlength="10" autocomplete="${registering?'new-password':'current-password'}" required><span class="field-hint">At least 10 characters.</span></div>`}${registering?`<div class="legal-consents"><label class="consent-row"><input type="checkbox" name="legal_agreement" required><span>I agree to the <a href="/terms.html" target="_blank" rel="noopener">Terms of Service</a> and acknowledge the <a href="/privacy.html" target="_blank" rel="noopener">Privacy Notice</a> (versions ${TERMS_VERSION} and ${PRIVACY_VERSION}).</span></label><label class="consent-row"><input type="checkbox" name="age_13_plus" required><span>I am at least 13 years old. Children under 13 may not create an account.</span></label><label class="consent-row"><input type="checkbox" name="guardian_permission" required><span>If I am under 18, my parent or guardian has reviewed these documents and given permission for me to use this app.</span></label></div>`:''}<button class="btn btn-primary" style="width:100%">${registering?'Create account':selectedAuthMode==='reset'?'Save new password':selectedAuthMode==='request-reset'?'Send reset instructions':'Sign in'}</button></form><div class="auth-links">${selectedAuthMode==='login'?`<button data-auth-mode="register">Create account</button><button data-auth-mode="request-reset">Forgot password?</button>`:`<button data-auth-mode="login">Back to sign in</button>${selectedAuthMode==='request-reset'?'<button data-auth-mode="reset">I have a reset code</button>':''}`}</div><p class="field-hint">Do not enter sensitive personal information. School-specific plans should be reviewed with a counselor.</p></section></div>`}
async function api(path,options={}){const r=await fetch(path,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'The request could not be completed.');return d}
function setAuthMode(mode){selectedAuthMode=mode;document.getElementById('authRoot').innerHTML=authPage();bindAuth()}
function bindAuth(){document.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>setAuthMode(b.dataset.authMode));const form=document.getElementById('authForm');if(!form)return;form.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));try{if(selectedAuthMode==='request-reset'){const result=await api('/api/auth/password-reset/request',{method:'POST',body:JSON.stringify({email:d.email})});toast(result.development_reset_code?`Local reset code: ${result.development_reset_code}`:result.message);return}if(selectedAuthMode==='reset'){await api('/api/auth/password-reset/complete',{method:'POST',body:JSON.stringify({token:d.token,password:d.password})});toast('Password updated. Sign in with your new password.');setAuthMode('login');return}const registering=selectedAuthMode==='register';await api(`/api/auth/${registering?'register':'login'}`,{method:'POST',body:JSON.stringify({email:d.email,password:d.password,...(registering?{legal_agreement:d.legal_agreement==='on',terms_version:TERMS_VERSION,privacy_version:PRIVACY_VERSION,age_13_plus:d.age_13_plus==='on',guardian_permission:d.guardian_permission==='on'}:{})})});await loadWorkspace()}catch(err){toast(err.message)}}}
function ensureAuthRoot(){let root=document.getElementById('authRoot');if(!root){root=document.createElement('div');root.id='authRoot';document.body.append(root)}return root}
async function loadWorkspace(){const me=await api('/api/auth/me');currentUser=me.user;if(!currentUser){document.querySelector('.app-shell').hidden=true;ensureAuthRoot().innerHTML=authPage();bindAuth();return}const d=await api('/api/bootstrap');state={...loadState(),...d,profile:{...seededProfile,...(d.profile||{})}};starterColleges=d.colleges||[];opportunities=d.opportunities||[];schoolCourses=[];document.querySelector('.app-shell').hidden=false;ensureAuthRoot().innerHTML='';setupNav();updateChrome();render();checkAI()}
function setupNav(){const navs=document.querySelectorAll('.main-nav');const secondary=navs[1];const entries=[['applications','Applications'],['studyPlan','Study planner'],['essays','Essay feedback'],['careers','Career explorer'],['feedback','Report a problem']];entries.forEach(([page,label])=>{if(!document.querySelector(`[data-page="${page}"]`)){const b=document.createElement('button');b.className='nav-item';b.dataset.page=page;b.innerHTML=`<span class="nav-icon">◇</span>${label}`;secondary.append(b)}});if(currentUser?.is_admin&&!document.querySelector('[data-page="admin"]')){const b=document.createElement('button');b.className='nav-item';b.dataset.page='admin';b.innerHTML='<span class="nav-icon">⚙</span>Admin';secondary.append(b)}const right=document.querySelector('.topbar-right');if(!document.getElementById('logoutButton')){const b=document.createElement('button');b.id='logoutButton';b.className='btn btn-quiet';b.textContent='Sign out';b.onclick=logout;right.prepend(b)}}
async function logout(){try{await api('/api/auth/logout',{method:'POST',body:'{}'})}catch{}currentUser=null;state=loadState();document.querySelector('.app-shell').hidden=true;setAuthMode('login')}
function updateChrome(){if(!currentUser)return;const p=state.profile||seededProfile;const full=`${p.firstName||'Student'} ${p.lastName||''}`.trim();document.getElementById('sideName').textContent=full;document.getElementById('sideGrade').textContent=`${p.grade||'9'}th grade · ${gradYear()}`;document.getElementById('avatar').textContent=(p.firstName||'S')[0].toUpperCase();document.getElementById('topAvatar').textContent=(p.firstName||'S')[0].toUpperCase();document.getElementById('taskCount').textContent=(state.tasks||[]).filter(t=>!t.done).length;document.getElementById('todayLabel').textContent=new Intl.DateTimeFormat('en-US',{weekday:'short',month:'short',day:'numeric'}).format(today)}
function nav(page){activePage=page;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.getElementById('crumbCurrent').textContent=({dashboard:'Overview',advisor:'AI advisor',roadmap:'My roadmap',courses:'Course planner',colleges:'College list',opportunities:'Opportunities',activities:'Activities',tutor:'Study tutor',tasks:'Tasks & deadlines',profile:'My profile',applications:'Applications',studyPlan:'Study planner',essays:'Essay feedback',careers:'Career explorer',admin:'Admin'})[page]||page;document.getElementById('sidebar').classList.remove('open');render()}
function render(){updateChrome();const root=document.getElementById('pageContainer');const pages={dashboard:dashboardPage,advisor:advisorPage,roadmap:roadmapPage,courses:coursesPage,colleges:collegesPage,opportunities:opportunitiesPage,activities:activitiesPage,tutor:tutorPage,tasks:tasksPage,profile:profilePage,applications:applicationsPage,studyPlan:studyPlanPage,essays:essaysPage,careers:careersPage,admin:adminPage};root.innerHTML=(pages[activePage]||dashboardPage)();bindPageEvents();bindExtraForms()}
function bindPageEvents(){document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>handleAction(el)));const form=document.getElementById('profileForm');if(form)form.addEventListener('submit',saveProfile);const search=document.getElementById('collegeSearch');if(search)search.addEventListener('input',()=>{const pos=search.selectionStart;collegeQuery=search.value;render();const next=document.getElementById('collegeSearch');next.focus();next.setSelectionRange(pos,pos)});const chat=document.getElementById('chatForm');if(chat)chat.addEventListener('submit',e=>{e.preventDefault();sendChat()});document.querySelectorAll('[data-prompt]').forEach(el=>el.addEventListener('click',()=>{document.getElementById('chatInput').value=el.dataset.prompt;sendChat()}));const tutor=document.getElementById('tutorForm');if(tutor)tutor.addEventListener('submit',e=>{e.preventDefault();tutorResponse()})}
async function saveProfile(e){e.preventDefault();const f=new FormData(e.currentTarget),p=state.profile,grade=f.get('grade');const names=f.get('courses').split('\n').map(x=>x.trim()).filter(Boolean);const old=p.courses||[];Object.assign(p,{firstName:f.get('firstName').trim(),lastName:f.get('lastName').trim(),grade,school:f.get('school').trim(),state:f.get('state').trim(),gpa:f.get('gpa').trim(),major:f.get('major').trim(),career:f.get('career').trim(),colleges:f.get('colleges').split(',').map(x=>x.trim()).filter(Boolean),courses:names.map(name=>({...old.find(c=>c.name===name),name,level:old.find(c=>c.name===name)?.level||'Standard',year:grade})),planned:f.get('planned').split('\n').map(x=>x.trim()).filter(Boolean).map(name=>({name,level:'Standard',year:String(Math.min(12,Number(grade)+1)),planned:true})),activities:f.get('activities').split('\n').map(x=>x.trim()).filter(Boolean),interests:f.get('interests').split(',').map(x=>x.trim()).filter(Boolean),goals:f.get('goals').trim()});try{await api('/api/profile',{method:'PUT',body:JSON.stringify({profile:p})});persist();render();toast('Profile saved')}catch(err){toast(err.message)}}
async function callAi(message,mode='advisor',history=[]){const path=mode==='tutor'?'/api/assistant/tutor':mode==='study_plan'?'/api/assistant/study-plan':mode==='essay_feedback'?'/api/assistant/essay-feedback':'/api/assistant/chat';return api(path,{method:'POST',body:JSON.stringify({message,mode,history,profile:state.profile})})}
function messageHTML(m){return `<div class="message ${m.role==='user'?'user':''}">${m.role==='assistant'?'<div class="message-mark"><img src="/assets/logo.png" alt=""></div>':''}<div><div class="message-bubble" style="white-space:pre-wrap">${esc(m.text)}</div>${m.role==='assistant'&&m.citations?.length?`<div class="citation-list"><strong>Sources · accessed ${esc(m.citations[0].accessed_at||'today')}</strong>${m.citations.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title||s.url)} ↗</a>`).join('')}</div>`:''}<div class="message-meta">${m.role==='user'?'You':'Your advisor'}</div></div></div>`}
async function sendChat(){const input=document.getElementById('chatInput'),text=input.value.trim();if(!text)return;const history=state.messages.slice(-20).map(m=>({role:m.role,content:m.text}));state.messages.push({role:'user',text});const pending={role:'assistant',text:'Thinking carefully…'};state.messages.push(pending);render();const entry=document.querySelector('.chat-messages');if(entry)entry.insertAdjacentHTML('beforeend','<div class="research-status">Working through your question…</div>');try{const result=await callAi(text,'advisor',history);pending.text=result.answer;pending.citations=result.sources||[];pending.intent=result.intent;pending.researched=result.researched;await persistNow();}catch(err){pending.text=`I couldn’t retrieve an AI response right now. ${err.message} Please verify current or time-sensitive details with an official source.`}render();const box=document.getElementById('chatMessages');if(box)box.scrollTop=box.scrollHeight}
async function persistNow(){if(!currentUser)return;clearTimeout(persistTimer);persistTimer=null;await queueStateSave()}
function coursesPage(){const p=state.profile,grades=[9,10,11,12];const catalog=schoolCourses.length?`<div class="panel"><div class="panel-head"><div><h2 class="panel-title">Verified school catalog</h2><div class="panel-sub">${esc(p.school)} · official source records</div></div></div>${schoolCourses.map(c=>`<div class="task-row"><div class="task-main"><strong>${esc(c.name)} · ${esc(c.level)}</strong><span>Grade ${esc(c.grade)}${c.prerequisites?` · Prerequisites: ${esc(c.prerequisites)}`:''} · ${esc(c.verification_status)}</span></div>${c.source_url?`<a href="${esc(c.source_url)}" target="_blank" rel="noopener">Source ↗</a>`:''}</div>`).join('')}</div>`:`<div class="panel"><p class="context-hint">No verified course catalog is on file for ${esc(p.school||'your school')}. Add your courses manually and confirm availability with a counselor.</p></div>`;if(!schoolCourses.length&&p.school)api('/api/school/courses').then(d=>{schoolCourses=d.courses||[];if(activePage==='courses')render()}).catch(()=>{});return `${pageHeader('PLAN WITH YOUR SCHOOL CATALOG','Course planner','Map current and future courses. Confirm every choice with your counselor.',`<button class="btn btn-primary" data-action="add-course">＋ Add a course</button>`)}<div class="panel"><div class="panel-head"><div><h2 class="panel-title">Your four-year view</h2><div class="panel-sub">Current courses, planned courses, and ideas to investigate</div></div>${badge(`${p.courses.length+p.planned.length} courses mapped`,'blue')}</div><div class="grid two-col">${grades.map(g=>{const list=[...p.courses,...p.planned].filter(c=>Number(c.year)===g);return `<div class="course-year"><div class="year-head"><h3>${['','Freshman','Sophomore','Junior','Senior'][g]} year</h3><span>GRADE ${g}${g===Number(p.grade)?' · CURRENT':''}</span></div><div class="course-list">${list.length?list.map(c=>`<div class="course-row"><span class="course-color" style="background:${c.planned?'#bc83e4':'#3f88f4'}"></span><span class="course-name">${esc(c.name)}</span><span class="course-level">${esc(c.level)}${c.planned?' · PLAN':''}</span></div>`).join(''):'<div class="empty-state" style="padding:16px">No courses added for this year yet.</div>'}<button class="course-add" data-action="add-course" data-year="${g}">＋ Add course</button></div></div>`}).join('')}</div></div>${catalog}<div class="grid two-col"><div class="panel"><h2 class="panel-title">Planning notes</h2><p class="context-hint">Investigate courses relevant to ${esc(p.major||'your interests')} if your school offers them and prerequisites fit. These are recommendations, not college requirements.</p></div><div class="panel"><h2 class="panel-title">Before you finalize</h2><p class="context-hint">Check graduation requirements, course availability, workload, and prerequisites with your school counselor.</p></div></div>`}
function applicationsPage(){const items=state.applications||[];return `${pageHeader('KEEP EACH APPLICATION ORGANIZED','Applications','Track colleges, deadlines, status, and what remains to prepare.',`<button class="btn btn-primary" data-action="new-application">＋ Add application</button>`)}<div class="panel">${items.length?items.map(a=>`<div class="task-row"><div class="task-main"><strong>${esc(a.college_name)}</strong><span>${a.due?`Due ${esc(a.due)} · `:''}${esc(a.notes||'Application checklist: essays, recommendations, transcript, testing, and financial aid.')}</span></div><select class="select-input" data-app-status="${esc(a.id)}">${['Not Started','In Progress','Submitted','Complete'].map(s=>`<option ${s===a.status?'selected':''}>${s}</option>`).join('')}</select><button class="course-remove" data-action="delete-application" data-id="${esc(a.id)}">×</button></div>`).join(''):'<div class="empty-state"><strong>No applications tracked yet.</strong>Add colleges and record deadlines, essays, recommendations, transcripts, and financial-aid steps.</div>'}</div>`}
function studyPlanPage(){return `${pageHeader('MAKE A REALISTIC STUDY PLAN','Study planner','Add tests, assignments, or projects and how much time you have available.')}<div class="grid two-col"><form id="studyForm" class="panel profile-form"><div class="field full"><label>Classes and deadlines</label><textarea class="textarea-input" name="message" required placeholder="Chemistry test Friday (hard); AP Government test Monday; history project next Wednesday"></textarea></div><div class="field"><label>Available study time</label><input class="text-input" name="availability" placeholder="90 minutes on weekdays, 2 hours Sunday" required></div><div class="field"><label>Study preferences</label><input class="text-input" name="preferences" placeholder="Short sessions, breaks, hardest class first"></div><div class="field-actions"><button class="btn btn-primary">Build study plan</button></div></form><div id="studyResult" class="panel"><h2 class="panel-title">Your plan will appear here</h2><p class="context-hint">The AI will balance deadline urgency with the time you have available.</p></div></div>`}
function essaysPage(){return `${pageHeader('KEEP YOUR VOICE','Essay feedback','Get coaching on structure, clarity, evidence, and voice. Feedback will not rewrite your essay.')}<form id="essayForm" class="panel profile-form"><div class="field"><label>Essay title</label><input class="text-input" name="title" placeholder="Personal statement draft"></div><div class="field full"><label>Essay prompt</label><textarea class="textarea-input" name="prompt" placeholder="Optional prompt or assignment instructions"></textarea></div><div class="field full"><label>Your draft</label><textarea class="textarea-input" name="body" required maxlength="30000" style="min-height:240px" placeholder="Paste your draft here"></textarea><span class="field-hint">Drafts are private to your account. Do not include sensitive personal details.</span></div><div class="field-actions"><button class="btn btn-primary">Save draft and request feedback</button></div></form><div id="essayResult"></div>`}
function careersPage(){return `${pageHeader('EXPLORE POSSIBILITY','Career explorer','Ask about responsibilities, skills, majors, preparation, and ways to explore more than one path.')}<div class="chat-layout"><form id="careerForm" class="panel profile-form"><div class="field full"><label>What are you curious about?</label><textarea class="textarea-input" name="message" required placeholder="Compare finance, economics research, and public policy careers for a high-school student"></textarea></div><button class="btn btn-primary">Explore careers</button></form><div id="careerResult" class="panel"><h2 class="panel-title">Start with a question</h2></div></div>`}
function adminPage(){if(!currentUser?.is_admin)return `${pageHeader('ADMINISTRATION','Access required','This area is available to configured administrators only.')}`;if(!adminOverview.loaded)Promise.all([api('/api/admin/overview'),api('/api/admin/records'),api('/api/admin/users')]).then(([o,r,u])=>{adminOverview={...o,...r,loaded:true};adminUsers=u.users||[];if(activePage==='admin')render()}).catch(e=>toast(e.message));return `${pageHeader('DATA QUALITY','Admin','Review records, feedback, and AI failures. Mark data verified only after checking the official source.')}<div class="grid three-col">${Object.entries(adminOverview.counts||{}).map(([k,v])=>`<div class="stat-card"><div class="stat-kicker">${esc(k.replaceAll('_',' ').toUpperCase())}</div><div class="stat-value">${v}</div></div>`).join('')}</div><div class="grid two-col"><form id="adminCollegeForm" class="panel profile-form"><h2 class="panel-title">Add college</h2><div class="field"><label>Name</label><input class="text-input" name="name" required></div><div class="field"><label>Location</label><input class="text-input" name="location"></div><div class="field full"><label>Majors, comma separated</label><input class="text-input" name="majors"></div><div class="field full"><label>Official admissions URL</label><input class="text-input" name="source" type="url" required></div><label><input type="checkbox" name="verified"> I reviewed and verified this information</label><button class="btn btn-primary">Save college</button></form><form id="adminSchoolForm" class="panel profile-form"><h2 class="panel-title">Add school</h2><div class="field"><label>Name</label><input class="text-input" name="name" required></div><div class="field"><label>Location</label><input class="text-input" name="location"></div><div class="field full"><label>Catalog URL</label><input class="text-input" name="catalog_url" type="url"></div><label><input type="checkbox" name="verified"> I reviewed and verified this information</label><button class="btn btn-primary">Save school</button></form></div><div class="panel"><h2 class="panel-title">User reports</h2>${(adminOverview.feedback||[]).map(f=>`<div class="task-row"><div class="task-main"><strong>${esc(f.category)}</strong><span>${esc(f.details||'No details')}</span></div><span>${esc(f.created_at)}</span></div>`).join('')||'<p class="context-hint">No reports yet.</p>'}</div><div class="panel"><h2 class="panel-title">Account access</h2>${adminUsers.map(u=>`<div class="task-row"><div class="task-main"><strong>${esc(u.email)}</strong><span>${u.is_admin?'Administrator':'Student'} · ${u.is_active?'Active':'Disabled'}</span></div><button class="btn btn-quiet" data-action="toggle-user" data-id="${u.id}" data-active="${u.is_active?'false':'true'}">${u.is_active?'Disable':'Enable'}</button></div>`).join('')}</div>`}
function bindExtraForms(){const appForm=document.getElementById('newApplicationForm');if(appForm)appForm.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(appForm));try{await api('/api/applications',{method:'POST',body:JSON.stringify(d)});state.applications=(await api('/api/applications')).applications;render()}catch(err){toast(err.message)}};const study=document.getElementById('studyForm');if(study)study.onsubmit=async e=>{e.preventDefault();const f=new FormData(study),out=document.getElementById('studyResult');out.innerHTML='<p class="thinking">Thinking through deadlines and available time…</p>';try{const result=await callAi(`${f.get('message')}\nAvailable time: ${f.get('availability')}\nPreferences: ${f.get('preferences')||'None shared'}`,'study_plan');out.innerHTML=`<div class="eyebrow">PERSONAL STUDY PLAN</div><div style="white-space:pre-wrap;line-height:1.7">${esc(result.answer)}</div>${citationsHTML(result.sources)}`}catch(err){out.textContent=`I couldn’t create the plan. ${err.message}`}};const essay=document.getElementById('essayForm');if(essay)essay.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(essay));try{const saved=await api('/api/essays',{method:'POST',body:JSON.stringify(d)});const out=document.getElementById('essayResult');out.innerHTML='<div class="panel thinking">Reviewing organization, clarity, grammar, structure, evidence, repetition, voice, and argumentation…</div>';const result=await api('/api/essays/feedback',{method:'POST',body:JSON.stringify({essay_id:saved.id})});out.innerHTML=`<div class="panel"><h2 class="panel-title">Coaching feedback</h2><div style="white-space:pre-wrap;line-height:1.7">${esc(result.answer)}</div>${citationsHTML(result.sources)}</div>`}catch(err){toast(err.message)}};const career=document.getElementById('careerForm');if(career)career.onsubmit=async e=>{e.preventDefault();const f=new FormData(career),out=document.getElementById('careerResult');out.innerHTML='<p class="thinking">Exploring career paths…</p>';try{const result=await callAi(f.get('message'),'advisor');out.innerHTML=`<div style="white-space:pre-wrap;line-height:1.7">${esc(result.answer)}</div>${citationsHTML(result.sources)}`}catch(err){out.textContent=`I couldn’t retrieve current career information. ${err.message}`}};const college=document.getElementById('adminCollegeForm');if(college)college.onsubmit=e=>submitAdmin(e,college,'college');const school=document.getElementById('adminSchoolForm');if(school)school.onsubmit=e=>submitAdmin(e,school,'school');document.querySelectorAll('[data-app-status]').forEach(s=>s.onchange=async()=>{const id=s.dataset.appStatus,item=state.applications.find(a=>a.id===id);try{await api('/api/applications',{method:'PUT',body:JSON.stringify({id,status:s.value,due:item?.due||'',notes:item?.notes||''})});item.status=s.value;toast('Application updated')}catch(err){toast(err.message)}})}
function citationsHTML(items=[]){return items?.length?`<div class="citation-list"><strong>Sources · accessed ${esc(items[0].accessed_at||'today')}</strong>${items.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title||s.url)} ↗</a>`).join('')}</div>`:''}
async function submitAdmin(e,form,type){e.preventDefault();const d=Object.fromEntries(new FormData(form));if(type==='college')d.majors=d.majors.split(',').map(x=>x.trim()).filter(Boolean);d.verified=!!form.querySelector('[name="verified"]')?.checked;try{await api(`/api/admin/records/${type}`,{method:'POST',body:JSON.stringify(d)});toast(`${type} saved`);render()}catch(err){toast(err.message)}}
function handleAction(el){const a=el.dataset.action,id=el.dataset.id;if(a==='new-application'){openModal(`<div class="modal-head"><h2>Add application</h2><button class="modal-close" data-action="close-modal">×</button></div><form id="newApplicationForm" class="modal-form"><div class="field"><label>College</label><input class="text-input" name="college_name" required></div><div class="field"><label>Deadline</label><input class="text-input" type="date" name="due"></div><div class="field"><label>Notes / checklist</label><textarea class="textarea-input" name="notes" placeholder="Essays, recommendations, transcript, testing, aid forms"></textarea></div><div class="field-actions"><button class="btn btn-quiet" type="button" data-action="close-modal">Cancel</button><button class="btn btn-primary">Add</button></div></form>`);bindExtraForms();return}if(a==='delete-application'){api(`/api/applications/${encodeURIComponent(id)}`,{method:'DELETE'}).then(()=>api('/api/applications')).then(d=>{state.applications=d.applications;render()}).catch(e=>toast(e.message));return}if(a==='toggle-user'){api(`/api/admin/users/${id}/active`,{method:'POST',body:JSON.stringify({active:el.dataset.active==='true'})}).then(()=>{adminOverview.loaded=false;render()}).catch(e=>toast(e.message));return}if(a==='close-modal'){closeModal();return}if(a==='add-task'){taskModal();return}if(a==='add-course'){courseModal(el.dataset.year||'');return}if(a==='remove-course'){const k=el.dataset.planned==='true'?'planned':'courses';state.profile[k]=state.profile[k].filter(c=>!(c.name===el.dataset.name&&Number(c.year)===Number(el.dataset.year)));persist();render();return}if(a==='college-detail'){collegeDetail(id);return}if(a==='save-college'){if(!state.savedColleges.includes(id))state.savedColleges.push(id);persist();collegeDetail(id);return}if(a==='unsave-college'){state.savedColleges=state.savedColleges.filter(x=>x!==id);persist();render();return}if(a==='add-college'){collegeModal();return}if(a==='toggle-opportunity'){state.savedOpportunities=state.savedOpportunities.includes(id)?state.savedOpportunities.filter(x=>x!==id):[...state.savedOpportunities,id];persist();render();return}if(a==='mark-applied'){if(state.completedOpportunities.includes(id)){state.completedOpportunities=state.completedOpportunities.filter(x=>x!==id);state.appliedOpportunities=state.appliedOpportunities.filter(x=>x!==id)}else if(state.appliedOpportunities.includes(id))state.completedOpportunities.push(id);else{state.appliedOpportunities.push(id);state.savedOpportunities=[...new Set([...state.savedOpportunities,id])]};persist();render();return}if(a==='opportunity-filter'){opportunityFilter=el.dataset.filter;render();return}if(a==='task-filter'){taskFilter=el.dataset.filter;render();return}if(a==='toggle-task'){state.tasks=state.tasks.map(t=>t.id===id?{...t,done:!t.done}:t);persist();render();return}if(a==='delete-task'){state.tasks=state.tasks.filter(t=>t.id!==id);persist();render();return}if(a==='roadmap-toggle'){state.completedRoadmap=state.completedRoadmap.includes(id)?state.completedRoadmap.filter(x=>x!==id):[...state.completedRoadmap,id];persist();render();return}if(a==='add-activity'){activityModal();return}if(a==='remove-activity'){state.profile.activities.splice(Number(el.dataset.index),1);persist();render();return}if(a==='new-feedback'){feedbackModal();return}legacyHandleAction(el)}
const legacyHandleAction=function(el){const a=el.dataset.action,id=el.dataset.id;if(a==='add-task')taskModal();else if(a==='add-course')courseModal(el.dataset.year||'');else if(a==='remove-course'){const arr=el.dataset.planned==='true'?'planned':'courses';state.profile[arr]=state.profile[arr].filter(c=>!(c.name===el.dataset.name&&Number(c.year)===Number(el.dataset.year)));persist();render()}else if(a==='college-detail')collegeDetail(id);else if(a==='save-college'){if(!state.savedColleges.includes(id))state.savedColleges.push(id);persist();collegeDetail(id);toast('Added to My Colleges')}else if(a==='unsave-college'){state.savedColleges=state.savedColleges.filter(x=>x!==id);persist();render()}else if(a==='add-college')collegeModal();else if(a==='toggle-opportunity'){state.savedOpportunities=state.savedOpportunities.includes(id)?state.savedOpportunities.filter(x=>x!==id):[...state.savedOpportunities,id];persist();render()}else if(a==='mark-applied'){if(state.completedOpportunities.includes(id)){state.completedOpportunities=state.completedOpportunities.filter(x=>x!==id);state.appliedOpportunities=state.appliedOpportunities.filter(x=>x!==id)}else if(state.appliedOpportunities.includes(id))state.completedOpportunities.push(id);else{state.appliedOpportunities.push(id);state.savedOpportunities=[...new Set([...state.savedOpportunities,id])]};persist();render()}else if(a==='opportunity-filter'){opportunityFilter=el.dataset.filter;render()}else if(a==='task-filter'){taskFilter=el.dataset.filter;render()}else if(a==='toggle-task'){state.tasks=state.tasks.map(t=>t.id===id?{...t,done:!t.done}:t);persist();render()}else if(a==='delete-task'){state.tasks=state.tasks.filter(t=>t.id!==id);persist();render()}else if(a==='roadmap-toggle'){state.completedRoadmap=state.completedRoadmap.includes(id)?state.completedRoadmap.filter(x=>x!==id):[...state.completedRoadmap,id];persist();render()}else if(a==='add-activity')activityModal();else if(a==='remove-activity'){state.profile.activities.splice(Number(el.dataset.index),1);persist();render()}}
document.addEventListener('change',e=>{if(e.target.matches('[data-app-status]'))return});
document.addEventListener('click',e=>{if(e.target.matches('#logoutButton'))logout()});
document.addEventListener('DOMContentLoaded',()=>{});
async function initApp(){const shell=document.querySelector('.app-shell');if(shell)shell.hidden=true;const root=ensureAuthRoot();try{const me=await api('/api/auth/me');currentUser=me.user;if(currentUser)await loadWorkspace();else{root.innerHTML=authPage();bindAuth()}}catch{root.innerHTML=`<div class="auth-shell"><section class="auth-card"><h1>Could not connect</h1><p>Start the Python server with <code>python app.py</code>, then reload this page.</p></section></div>`}}
setupAuthDelegation();function setupAuthDelegation(){document.addEventListener('click',e=>{const b=e.target.closest('[data-auth-mode]');if(b)setAuthMode(b.dataset.authMode)})}
initApp();
const originalProfilePage=profilePage;
profilePage=function(){const p=state.profile;return originalProfilePage()+`<form id="profileExtrasForm" class="panel profile-form"><h2 class="panel-title field full">More of your journey</h2>${[['awards','Awards'],['competitions','Competitions'],['volunteer','Volunteer experience'],['work','Work experience'],['internships','Internships']].map(([key,label])=>`<div class="field"><label>${label}</label><textarea class="textarea-input" name="${key}" placeholder="One item per line">${esc((p[key]||[]).join('\n'))}</textarea></div>`).join('')}<div class="field-actions"><button class="btn btn-primary">Save additional profile details</button></div></form><div class="panel"><h2 class="panel-title">Account and privacy</h2><p class="context-hint">Your profile, conversations, essays, applications, and tasks are saved to this account. You can sign out at any time or permanently delete the account and its private records.</p><button class="btn btn-quiet" data-action="delete-account">Delete account</button></div>`};
const originalTutorResponse=tutorResponse;
tutorResponse=async function(){const course=document.getElementById('tutorCourse').value,mode=document.getElementById('tutorMode').value,q=document.getElementById('tutorQuestion').value.trim();if(!q){toast('Add a concept or question to get started');return}const answer=document.getElementById('tutorAnswer');answer.innerHTML='<div class="panel thinking" style="margin-top:16px">Working through this with you…</div>';try{const result=await callAi(`Course: ${course}\nLearning mode: ${mode}\nStudent question or topic: ${q}`,'tutor');answer.innerHTML=`<div class="panel"><div class="eyebrow">AI TUTOR · ${esc(course.toUpperCase())}</div><p style="white-space:pre-wrap;line-height:1.7">${esc(result.answer)}</p>${citationsHTML(result.sources)}<span class="field-hint">Work through the reasoning, then check your class materials and teacher guidance.</span></div>`}catch(err){answer.innerHTML=`<div class="panel"><p>${esc(err.message)}</p><p class="field-hint">Try again later or ask your teacher for support.</p></div>`}};
function feedbackPage(){return `${pageHeader('HELP IMPROVE ACCURACY','Report a problem','Tell us if guidance was incorrect, outdated, missing sources, or not useful.')}<form id="feedbackForm" class="panel profile-form"><div class="field"><label>What went wrong?</label><select class="select-input" name="category">${['Incorrect information','Outdated information','Missing source','Bad recommendation','Other problem'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field full"><label>Details</label><textarea class="textarea-input" name="details" maxlength="4000" placeholder="Include what page or answer this relates to. Do not include private information."></textarea></div><button class="btn btn-primary">Send report</button></form>`}
async function deleteAccountFlow(){openModal(`<div class="modal-head"><div><h2>Delete account</h2><p>This permanently deletes your profile and private planning data.</p></div><button class="modal-close" data-action="close-modal">×</button></div><form id="deleteAccountForm" class="modal-form"><div class="field"><label>Confirm password</label><input class="text-input" name="password" type="password" required autocomplete="current-password"></div><div class="field-actions"><button class="btn btn-quiet" type="button" data-action="close-modal">Cancel</button><button class="btn btn-primary">Delete account</button></div></form>`);document.getElementById('deleteAccountForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/account/delete',{method:'POST',body:JSON.stringify({password:new FormData(e.currentTarget).get('password')})});closeModal();currentUser=null;document.querySelector('.app-shell').hidden=true;setAuthMode('register')}catch(err){toast(err.message)}}}
function feedbackSubmit(){const f=document.getElementById('feedbackForm');if(f)f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));if(d.category==='Other problem')d.category='Other';try{await api('/api/feedback',{method:'POST',body:JSON.stringify(d)});f.reset();toast('Report received. Thank you.')}catch(err){toast(err.message)}}}
const oldRender=render;
render=function(){const root=document.getElementById('pageContainer');const pages={feedback:feedbackPage};if(activePage==='feedback'){updateChrome();root.innerHTML=feedbackPage();bindPageEvents();feedbackSubmit();bindExtraForms();return}oldRender()};
const oldHandle=handleAction;
handleAction=function(el){if(el.dataset.action==='delete-account'){deleteAccountFlow();return}oldHandle(el)};
const oldBindExtra=bindExtraForms;
bindExtraForms=function(){oldBindExtra();feedbackSubmit()};
const bindFormsWithExtraProfile=bindExtraForms;
bindExtraForms=function(){bindFormsWithExtraProfile();const form=document.getElementById('profileExtrasForm');if(form)form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);for(const k of ['awards','competitions','volunteer','work','internships'])state.profile[k]=f.get(k).split('\n').map(x=>x.trim()).filter(Boolean);try{await api('/api/profile',{method:'PUT',body:JSON.stringify({profile:state.profile})});toast('Profile details saved')}catch(err){toast(err.message)}}};
const existingAdminPage=adminPage;
adminPage=function(){return existingAdminPage()+`<div class="grid two-col"><form id="adminCourseForm" class="panel profile-form"><h2 class="panel-title field full">Add a school course</h2><div class="field full"><label>School</label><select class="select-input" name="school_id" required>${(adminOverview.schools||[]).map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(s.location)}</option>`).join('')}</select></div><div class="field"><label>Course name</label><input class="text-input" name="name" required></div><div class="field"><label>Level</label><input class="text-input" name="level" placeholder="AP, Honors, Dual Enrollment"></div><div class="field"><label>Grade</label><input class="text-input" name="grade" placeholder="11"></div><div class="field"><label>Credits</label><input class="text-input" name="credits" type="number" step="0.5"></div><div class="field full"><label>Prerequisites</label><input class="text-input" name="prerequisites"></div><div class="field full"><label>Description</label><textarea class="textarea-input" name="description"></textarea></div><div class="field full"><label>Official source URL</label><input class="text-input" type="url" name="source_url"></div><label class="field full"><input type="checkbox" name="verified"> Reviewed against official source</label><button class="btn btn-primary">Add course</button></form><form id="adminOpportunityForm" class="panel profile-form"><h2 class="panel-title field full">Add opportunity</h2><div class="field"><label>Name</label><input class="text-input" name="name" required></div><div class="field"><label>Category</label><select class="select-input" name="category"><option>Internships</option><option>Competitions</option><option>Summer programs</option><option>Research</option><option>Volunteering</option><option>Scholarships</option><option>Leadership programs</option></select></div><div class="field full"><label>Description</label><textarea class="textarea-input" name="description"></textarea></div><div class="field full"><label>Eligibility</label><textarea class="textarea-input" name="eligibility"></textarea></div><div class="field"><label>Deadline</label><input class="text-input" name="deadline"></div><div class="field"><label>Cost</label><input class="text-input" name="cost"></div><div class="field"><label>Location</label><input class="text-input" name="location"></div><div class="field"><label>Interests</label><input class="text-input" name="interests" placeholder="Comma separated"></div><div class="field full"><label>Official source URL</label><input class="text-input" type="url" name="official_url" required></div><div class="field full"><label>Application info</label><textarea class="textarea-input" name="application_info"></textarea></div><label class="field full"><input type="checkbox" name="verified"> Reviewed against official source</label><button class="btn btn-primary">Add opportunity</button></form></div><div class="panel"><h2 class="panel-title">Recent source history</h2>${(adminOverview.sourceHistory||[]).map(s=>`<div class="task-row"><div class="task-main"><strong>${esc(s.title)}</strong><span>${esc(s.organization)} · retrieved ${esc(s.retrieved_at)} · ${esc(s.verification_status)}</span></div><a href="${esc(s.url)}" target="_blank" rel="noopener">Open ↗</a></div>`).join('')||'<p class="context-hint">No source records yet.</p>'}<h2 class="panel-title" style="margin-top:18px">AI failures</h2>${(adminOverview.aiFailures||[]).map(f=>`<div class="task-row"><div class="task-main"><strong>${esc(f.intent)} · ${esc(f.error)}</strong><span>${esc(f.query)}</span></div><span>${esc(f.created_at)}</span></div>`).join('')||'<p class="context-hint">No recent AI failures.</p>'}</div>`};
const bindAdminMore=bindExtraForms;
bindExtraForms=function(){bindAdminMore();const course=document.getElementById('adminCourseForm');if(course)course.onsubmit=e=>submitAdmin(e,course,'course');const opp=document.getElementById('adminOpportunityForm');if(opp)opp.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(opp));d.interests=d.interests.split(',').map(x=>x.trim()).filter(Boolean);d.verified=!!opp.querySelector('[name="verified"]')?.checked;try{await api('/api/admin/records/opportunity',{method:'POST',body:JSON.stringify(d)});toast('Opportunity saved');adminOverview.loaded=false;render()}catch(err){toast(err.message)}}};
const adminWithCreateForms=adminPage;
adminPage=function(){const base=adminWithCreateForms();if(!currentUser?.is_admin)return base;const groups=[['college','colleges','Colleges'],['school','schools','Schools'],['course','courses','Courses'],['opportunity','opportunities','Opportunities']];return base+`<div class="panel"><div class="panel-head"><div><h2 class="panel-title">Manage existing records</h2><div class="panel-sub">Update deadlines, source links, and verification status.</div></div></div>${groups.map(([kind,key,label])=>`<h3>${label}</h3>${(adminOverview[key]||[]).map(r=>`<div class="task-row"><div class="task-main"><strong>${esc(r.name)}</strong><span>${esc(r.verification_status||'unverified')}${r.last_verified?` · last verified ${esc(r.last_verified)}`:''}</span></div><button class="btn btn-quiet" data-action="admin-edit" data-type="${kind}" data-id="${r.id}">Edit</button></div>`).join('')||'<p class="context-hint">No records.</p>'}`).join('')}</div>`};
function adminEditModal(kind,id){const rows={college:adminOverview.colleges||[],school:adminOverview.schools||[],course:adminOverview.courses||[],opportunity:adminOverview.opportunities||[]};const r=rows[kind].find(x=>String(x.id)===String(id));if(!r)return toast('Record not found. Refresh the admin page.');const specs={college:[['name','Name',r.name],['location','Location',r.location],['majors','Majors, comma separated',JSON.parse(r.majors_json||'[]').join(', ')],['summary','Summary',r.summary],['source','Admissions source URL',r.admissions_url],['preparation_url','Academic preparation URL',r.preparation_url],['financial_aid_url','Financial aid URL',r.financial_aid_url]],school:[['name','Name',r.name],['location','Location',r.location],['website','Website',r.website],['catalog_url','Catalog URL',r.catalog_url]],course:[['name','Name',r.name],['level','Level',r.level],['grade','Grade',r.grade],['prerequisites','Prerequisites',r.prerequisites],['credits','Credits',r.credits??''],['description','Description',r.description],['source_url','Official source URL',r.source_url]],opportunity:[['name','Name',r.name],['category','Category',r.category],['description','Description',r.description],['eligibility','Eligibility',r.eligibility],['deadline','Deadline',r.deadline],['cost','Cost',r.cost],['location','Location',r.location],['interests','Interests, comma separated',JSON.parse(r.interests_json||'[]').join(', ')],['official_url','Official source URL',r.official_url],['application_info','Application information',r.application_info]]}[kind];openModal(`<div class="modal-head"><div><h2>Edit ${kind}</h2><p>Changes are recorded in source history when a source URL is provided.</p></div><button class="modal-close" data-action="close-modal">×</button></div><form class="modal-form" id="adminEditForm">${specs.map(([key,label,value])=>`<div class="field"><label>${esc(label)}</label><input class="text-input" name="${key}" value="${esc(value??'')}" ${/URL/.test(label)?'type="url"':''}></div>`).join('')}<label><input type="checkbox" name="verified" ${r.verification_status==='verified'?'checked':''}> Mark verified after reviewing this source</label><div class="field-actions"><button type="button" class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary">Save record</button></div></form>`);const form=document.getElementById('adminEditForm');form.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));data.verified=!!form.querySelector('[name="verified"]')?.checked;if(kind==='college')data.majors=data.majors.split(',').map(x=>x.trim()).filter(Boolean);if(kind==='opportunity')data.interests=data.interests.split(',').map(x=>x.trim()).filter(Boolean);try{await api(`/api/admin/records/${kind}/${id}`,{method:'PUT',body:JSON.stringify(data)});closeModal();adminOverview.loaded=false;render();toast('Record updated')}catch(err){toast(err.message)}}}
const handleBeforeAdminEdit=handleAction;
handleAction=function(el){if(el.dataset.action==='admin-edit'){adminEditModal(el.dataset.type,el.dataset.id);return}handleBeforeAdminEdit(el)};
